import katex from './vendor/katex/katex.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const MATH_TEMPLATES=[['Fraction','\u005cfrac{a}{b}'],['Square root','\u005csqrt{x}'],['Power','x^{2}'],['Subscript','x_{1}'],['Integral','\u005cint_{a}^{b} f(x)\u005c,dx'],['Sum','\u005csum_{i=1}^{n} i'],['Pi','\u005cpi'],['Theta','\u005ctheta'],['Plus/minus','\u005cpm'],['Not equal','\u005cne'],['Less/equal','\u005cle'],['Times','\u005ctimes'],['Matrix','\u005cbegin{pmatrix}a&b\u005c\u005cc&d\u005cend{pmatrix}']];
export function mathHTML(value){if(!value)return '';try{return katex.renderToString(String(value).slice(0,2000),{output:'mathml',throwOnError:false,trust:false,strict:'ignore',maxExpand:100,maxSize:20});}catch{return escape(value);}}
export function mathText(value){return String(value??'').split(/(\$\$[\s\S]*?\$\$|\$[^$\n]+\$|\\\([\s\S]*?\\\))/g).map(s=>s.startsWith('$$')?mathHTML(s.slice(2,-2)):s.startsWith('$')?mathHTML(s.slice(1,-1)):s.startsWith('\u005c(')?mathHTML(s.slice(2,-2)):escape(s)).join('');}
export function mathsPalette(target){return `<div class="quiz-maths-palette" aria-label="Maths symbols">${MATH_TEMPLATES.map(([label,code])=>`<button type="button" data-math-target="${escape(target)}" data-math-code="${escape(code)}" title="${escape(label)}">${escape(label)}</button>`).join('')}</div>`;}
export function bindMaths(root){root.addEventListener('click',ev=>{const b=ev.target.closest('[data-math-code]');if(!b)return;const input=b.dataset.mathTarget==='formula'?b.closest('[data-quiz-question]').querySelector('[data-q="formula"]'):b.closest('[data-quiz-answer]').querySelector('[data-math-answer]');if(!input||input.readOnly)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(b.dataset.mathCode,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();});root.addEventListener('input',ev=>{const input=ev.target;if(input.matches('[data-q="formula"]')){const p=input.closest('[data-quiz-question]').querySelector('[data-formula-preview]');if(p)p.innerHTML=mathHTML(input.value);}if(input.matches('[data-math-answer]')){const p=input.closest('[data-quiz-answer]').querySelector('[data-math-answer-preview]');if(p)p.innerHTML=mathHTML(input.value);}});}
